# Flutter's Gradle plugin already contributes the core Flutter rules; these
# cover the native-backed plugins Nex depends on.

# sqlite3 / sqlite3_flutter_libs load native symbols reflectively.
-keep class com.tekartik.** { *; }
-keep class org.sqlite.** { *; }

# just_audio / just_audio_windows and the ExoPlayer backend.
-keep class com.google.android.exoplayer2.** { *; }
-dontwarn com.google.android.exoplayer2.**

# record uses MediaRecorder reflection on some OEM ROMs.
-keep class com.llfbandit.record.** { *; }

# Keep the widget provider referenced only from AndroidManifest.xml.
-keep class com.sanyzrn.nex.CaptureWidgetProvider { *; }
-keep class com.sanyzrn.nex.MainActivity { *; }

# Strip verbose logging from release builds.
-assumenosideeffects class android.util.Log {
    public static *** d(...);
    public static *** v(...);
}

/// Nex — Core domain layer.
///
/// Pure Dart. Zero Flutter dependency. Zero storage dependency.
///
/// Dependency rule (06-development.md): apps/* -> packages/core, and
/// packages/data -> packages/core. Core sits at the bottom and depends on
/// nothing in this repository.
///
/// This library used to contain:
///
///   export 'package:nex_data/nex_data.dart';
///
/// which handed every caller the whole persistence layer — NexDatabase,
/// NoteRepository, SyncClient and the raw SQLite types — and made the
/// documented layering decorative. It also dragged sqlite3 FFI, archive and
/// http into packages/ui, a package that renders widgets.
library nex_core;

// Domain models.
export 'models/note.dart';
export 'models/tag.dart';

// Ports: the contracts the app and the data layer agree on.
export 'ports/media_picker.dart';
export 'ports/note_repository.dart';
export 'ports/sync_port.dart';

// Domain services.
export 'ai/ai_adapter.dart';
export 'ai/ai_adapter_binding.dart';
export 'ai/ai_capabilities.dart';
export 'ai/enrichment_service.dart';
export 'ai/on_device_ai_adapter.dart';
export 'capture/capture_service.dart';
export 'sync/field_aware_merger.dart';

import '../models/note.dart';

/// Storage contract for notes.
///
/// Declared in core so the application and the AI/enrichment services depend on
/// a behaviour, not on SQLite. packages/data provides the implementation.
///
/// Every method is asynchronous by design: the concrete implementation runs on
/// a worker isolate (package:sqlite3 is a synchronous FFI binding, so a direct
/// call blocks whichever isolate makes it).
abstract interface class NoteRepository {
  Future<Note> insert(Note note);

  Future<Note?> byId(String id);

  Future<void> updateContent(String id, String content);

  /// Soft delete. Tombstones propagate through sync; the payload is erased by
  /// the merge layer, not retained behind a flag.
  Future<void> softDelete(String id);

  Future<List<Note>> timeline({int limit, int offset});

  Future<List<Note>> search(String query);

  Future<void> setTags(String noteId, List<String> tagNames);

  /// Copies the live database to a timestamped file inside [backupDir].
  Future<void> backup(String backupDir);

  /// Writes a portable archive and returns its path.
  Future<String> exportArchive({
    required String outputPath,
    required String mediaRoot,
  });
}

/// Outcome of one sync cycle.
class SyncResult {
  const SyncResult({
    required this.pushed,
    required this.pulled,
    required this.cursor,
    this.hasMore = false,
  });

  final int pushed;
  final int pulled;

  /// Opaque server cursor. This is a monotonic sequence value, not a timestamp:
  /// the previous protocol compared a Node-generated timestamp against
  /// PostgreSQL-generated row stamps, and any clock skew dropped rows forever.
  final String cursor;

  final bool hasMore;
}

/// Transport contract for v2 sync. Declared in core; implemented in data.
abstract interface class SyncPort {
  Future<SyncResult> sync();

  void close();
}

/// Where a piece of media came from.
enum MediaSource { camera, gallery }

/// A file the user chose or captured.
class CapturedMedia {
  const CapturedMedia({required this.path, required this.name});

  final String path;
  final String name;
}

/// Platform-capability port for media capture.
///
/// image_picker has no endorsed Windows implementation, and Windows is a
/// first-class v1 target. Without a capability abstraction each screen had to
/// remember to branch on Platform.is* checks, and a missed branch produced a
/// MissingPluginException at the exact moment the user tried to capture.
///
/// UI code must read [supportsCamera] / [supportsGallery] and never inspect the
/// platform directly.
abstract interface class MediaPicker {
  bool get supportsCamera;

  bool get supportsGallery;

  /// Returns null when the user cancels.
  Future<CapturedMedia?> pickImage(MediaSource source);
}

import 'dart:convert';
import 'dart:io';

import 'package:nex_core/nex_core.dart';
import 'package:test/test.dart';

/// Cross-language conformance suite.
///
/// This file and apps/backend/src/services/merge.conformance.test.ts consume
/// the identical corpus at spec/merge-conformance.json. If the Dart and
/// TypeScript implementations ever disagree on a single case, one of the two
/// suites fails.
///
/// The two implementations were previously hand-maintained ports with separate
/// fixtures, so divergence was undetectable — which is exactly how the
/// localeCompare ordering defect survived on the server side.
void main() {
  final specFile = File('../../spec/merge-conformance.json');

  late List<dynamic> cases;

  setUpAll(() {
    expect(
      specFile.existsSync(),
      isTrue,
      reason: 'spec/merge-conformance.json must be reachable from packages/core',
    );
    cases = jsonDecode(specFile.readAsStringSync()) as List<dynamic>;
    expect(cases, isNotEmpty);
  });

  test('corpus is non-empty', () {
    expect(cases.length, greaterThan(0));
  });

  group('conformance', () {
    setUp(() {});

    test('every case matches, in both argument orders', () {
      for (final raw in cases) {
        final testCase = raw as Map<String, dynamic>;
        final name = testCase['name'] as String;

        final a = MergeableNote.fromJson(
          testCase['a'] as Map<String, dynamic>,
        );
        final b = MergeableNote.fromJson(
          testCase['b'] as Map<String, dynamic>,
        );
        final expected = testCase['expected'] as Map<String, dynamic>;

        expect(
          FieldAwareMerger.merge(a, b).toJson(),
          equals(expected),
          reason: 'case: ' + name,
        );

        // ADR-020 requires commutativity: two devices resolving the same pair
        // in opposite argument order must reach the same state.
        expect(
          FieldAwareMerger.merge(b, a).toJson(),
          equals(expected),
          reason: 'case (commutative): ' + name,
        );
      }
    });
  });
}

